/*# sourceURL=elementor-frontend-inline-css */

.dgs-v1215,
.dgs-v1215 * {
  box-sizing: border-box !important;
  font-family: "Manrope", Inter, Arial, sans-serif !important;
}

.dgs-v1215 {
  --v1215-outline-gradient: linear-gradient(
    135deg,
    rgba(0,212,255,.95),
    rgba(106,76,255,.85),
    rgba(253,92,98,.95),
    rgba(247,215,87,.85)
  );
  position: relative !important;
  overflow: hidden !important;
  background: #020202 !important;
  color: #fff !important;
}

.dgs-v1215 a {
  color: inherit !important;
  text-decoration: none !important;
}

.dgs-v1215-shell {
  width: min(1480px, calc(100% - 36px)) !important;
  margin: 0 auto !important;
  position: relative !important;
  z-index: 2 !important;
}

.dgs-v1215-proof-stack {
  position: relative !important;
  padding: clamp(82px, 10vw, 150px) 0 !important;
}

.dgs-v1215-section-head {
  width: min(100%, 1280px) !important;
  max-width: 1280px !important;
  margin: 0 auto clamp(34px, 4vw, 58px) !important;
  text-align: center !important;
}

.dgs-v1215-section-kicker {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 10px !important;
  padding: 9px 13px !important;
  border-radius: 999px !important;
  border: 1px solid rgba(255,255,255,.14) !important;
  background: rgba(255,255,255,.055) !important;
  color: rgba(255,255,255,.78) !important;
  font-size: clamp(10px,.8vw,12px) !important;
  line-height: 1.25 !important;
  letter-spacing: .11em !important;
  text-transform: uppercase !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
  margin: 0 auto clamp(20px,2.5vw,30px) !important;
}

.dgs-v1215-section-head h2 {
  max-width: 1240px !important;
  margin: 0 auto !important;
  color: rgba(255,255,255,.96) !important;
  font-size: clamp(3.2rem, 5vw, 6.1rem) !important;
  line-height: 1.04 !important;
  letter-spacing: -.06em !important;
  font-weight: 800 !important;
  text-align: center !important;
  text-wrap: balance !important;
}

.dgs-v1215-section-head p {
  max-width: 980px !important;
  margin: 24px auto 0 !important;
  color: rgba(255,255,255,.66) !important;
  font-size: clamp(15px,1.05vw,18px) !important;
  line-height: 1.72 !important;
  text-align: center !important;
}

.dgs-v1215-logo-marquee {
  overflow: hidden !important;
  border-radius: 34px !important;
  border: 1px solid rgba(255,255,255,.12) !important;
  background: rgba(255,255,255,.08) !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
}

.dgs-v1215-logo-track {
  display: grid !important;
  grid-template-columns: repeat(5, minmax(170px, 1fr)) !important;
  gap: 1px !important;
}

.dgs-v1215-logo-tile {
  position: relative !important;
  min-height: 136px !important;
  padding: 26px 24px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  overflow: visible !important;
  text-align: center !important;
  background: rgba(255,255,255,.075) !important;
  transition: background .28s ease, transform .28s ease !important;
}

.dgs-v1215-logo-tile:hover {
  background: rgba(255,255,255,.11) !important;
  transform: translateY(-3px) !important;
}

.dgs-v1215-logo-tile img {
  width: 100% !important;
  max-width: 175px !important;
  max-height: 72px !important;
  height: auto !important;
  object-fit: contain !important;
  object-position: center !important;
  display: block !important;
  opacity: .96 !important;
  filter: none !important;
}

.dgs-v1215-logo-tile:hover img {
  opacity: 1 !important;
  filter: none !important;
}

@property --dgs-spot-rotate {
  syntax: "<angle>";
  initial-value: 132deg;
  inherits: false;
}

.dgs-v1215-logo-tile.dgs-v1215-logo-text {
  isolation: isolate !important;
  overflow: visible !important;
  min-height: 136px !important;
  background: rgba(255,255,255,.065) !important;
  border: 1px solid rgba(255,255,255,.10) !important;
  color: rgba(255,255,255,.88) !important;
  font-size: clamp(13px,.95vw,17px) !important;
  font-weight: 800 !important;
  letter-spacing: .11em !important;
  line-height: 1.35 !important;
  text-transform: uppercase !important;
  text-shadow: 0 0 18px rgba(255,255,255,.18) !important;
  cursor: pointer !important;
}

.dgs-v1215-logo-tile.dgs-v1215-logo-text::before {
  content: "" !important;
  position: absolute !important;
  inset: -2px !important;
  z-index: -2 !important;
  background: linear-gradient(
    var(--dgs-spot-rotate),
    #72c1d8 0%,
    #634dbc 32%,
    #ea3f8b 66%,
    #ffae33 100%
  ) !important;
  animation: dgsSpotBorderSpin 3.2s linear infinite !important;
}

.dgs-v1215-logo-tile.dgs-v1215-logo-text::after {
  content: "" !important;
  position: absolute !important;
  inset: 2px !important;
  z-index: -1 !important;
  background: linear-gradient(135deg, rgba(30,24,42,.96), rgba(18,16,24,.94)) !important;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.06), 0 0 36px rgba(234,63,139,.18) !important;
}

.dgs-v1215-logo-tile.dgs-v1215-logo-text:focus-visible {
  outline: 3px solid #72c1d8 !important;
  outline-offset: 6px !important;
}

@keyframes dgsSpotBorderSpin {
  0% { --dgs-spot-rotate: 0deg; }
  100% { --dgs-spot-rotate: 360deg; }
}

@media (max-width: 1180px) {
  .dgs-v1215-logo-track {
    grid-template-columns: repeat(4, minmax(150px, 1fr)) !important;
  }
}

@media (max-width: 860px) {
  .dgs-v1215-shell {
    width: min(100% - 28px, 1480px) !important;
  }

  .dgs-v1215-logo-track {
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  }

  .dgs-v1215-logo-tile {
    min-height: 118px !important;
    padding: 20px 16px !important;
  }

  .dgs-v1215-logo-tile img {
    max-width: 160px !important;
    max-height: 70px !important;
  }
}

@media (max-width: 560px) {
  .dgs-v1215-shell {
    width: min(100% - 24px, 1480px) !important;
  }

  .dgs-v1215-proof-stack {
    padding: 64px 0 !important;
  }

  .dgs-v1215-section-head h2 {
    font-size: clamp(2.6rem, 11vw, 4rem) !important;
    line-height: 1.08 !important;
  }

  .dgs-v1215-logo-track {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .dgs-v1215-logo-tile,
  .dgs-v1215-logo-tile.dgs-v1215-logo-text {
    min-height: 104px !important;
    padding: 18px 14px !important;
  }

  .dgs-v1215-logo-tile img {
    max-width: 145px !important;
    max-height: 62px !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .dgs-v1215-logo-tile.dgs-v1215-logo-text::before {
    animation: none !important;
  }
}

/* LLM Upgrade / Proof Section */
.llm-upgrade,
.llm-upgrade * {
  box-sizing: border-box;
  font-family: 'DM Sans', Arial, sans-serif;
}

.llm-upgrade {
  --bg: #07060D;
  --bg2: #0D0B18;
  --bg3: #141122;
  --silver: #F0EDF8;
  --body: #C8C5D8;
  --muted: #8A87A0;
  --dim: #5C596E;
  --line: rgba(255,255,255,.08);
  --ln2: rgba(255,255,255,.15);
  --green: #22C55E;
  color: var(--body);
  background: #000000;
}

.llm-upgrade img {
  display: block;
  max-width: 100%;
}

.llm-upgrade .w {
  max-width: 1360px;
  margin: 0 auto;
  padding: 0 24px;
}

.llm-upgrade .ws {
  max-width: 860px;
  margin: 0 auto;
  padding: 0 24px;
}

.llm-upgrade .sec {
  padding: 72px 0;
  border-bottom: 1px solid var(--line);
}

.llm-upgrade .sh {
  text-align: center;
  margin-bottom: 38px;
}

.llm-upgrade .ew {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .22em;
  text-transform: uppercase;
  margin-bottom: 14px;
}

.llm-upgrade .ewl {
  width: 18px;
  height: 1px;
  background: linear-gradient(90deg,#E8612A,#6247B0);
}

.llm-upgrade .gt,
.llm-upgrade .ewt {
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .sh h2 {
  font-size: clamp(30px,4vw,48px);
  line-height: 1.08;
  letter-spacing: -1.5px;
  color: var(--silver);
  margin: 0 0 10px;
}

.llm-upgrade .sh p {
  font-size: 15px;
  color: var(--muted);
  max-width: 780px;
  margin: 0 auto;
  line-height: 1.7;
}

@keyframes llmGradientShift {
  0%,100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

/* LLM-Style Case Studies */
.llm-upgrade .csg {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
}

.llm-upgrade .csc {
  border-radius: 18px;
  border: 1px solid var(--line);
  background: var(--bg2);
  overflow: hidden;
  cursor: pointer;
  position: relative;
  transition: .3s;
}

.llm-upgrade .csc::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg,#E8612A,#C43F7A,#6247B0);
  z-index: 2;
}

.llm-upgrade .csc:hover {
  transform: translateY(-7px);
  border-color: var(--ln2);
  box-shadow: 0 28px 70px rgba(0,0,0,.5);
}

.llm-upgrade .csss {
  height: 190px;
  overflow: hidden;
  position: relative;
}

.llm-upgrade .csss::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 55px;
  background: linear-gradient(to top,var(--bg2),transparent);
}

.llm-upgrade .csss img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
}

.llm-upgrade .csbody {
  padding: 22px 26px 24px;
}

.llm-upgrade .cslogo {
  height: 30px;
  margin-bottom: 13px;
}

.llm-upgrade .cslogo img {
  height: 100%;
  width: auto;
  object-fit: contain;
}

.llm-upgrade .cstag {
  display: inline-block;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  padding: 4px 11px;
  border-radius: 100px;
  margin-bottom: 12px;
  background: rgba(232,97,42,.1);
  color: #E8612A;
  border: 1px solid rgba(232,97,42,.2);
}

.llm-upgrade .csbody h3 {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -.4px;
  color: var(--silver);
  margin: 0 0 9px;
  line-height: 1.3;
}

.llm-upgrade .csbody > p {
  font-size: 13px;
  color: var(--muted);
  line-height: 1.68;
  margin: 0 0 18px;
}

.llm-upgrade .csnums {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 9px;
  margin-bottom: 14px;
}

.llm-upgrade .cnum {
  text-align: center;
  padding: 12px 5px;
  background: rgba(255,255,255,.03);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.llm-upgrade .cnum strong {
  display: block;
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .cnum span {
  font-size: 10px;
  color: var(--dim);
  text-transform: uppercase;
}

.llm-upgrade .csview {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 500;
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .csft {
  padding: 12px 26px;
  border-top: 1px solid var(--line);
  display: flex;
  align-items: center;
  gap: 9px;
}

.llm-upgrade .csav {
  width: 25px;
  height: 25px;
  border-radius: 6px;
  font-size: 9px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg,#E8612A,#C43F7A);
  color: #fff;
  flex-shrink: 0;
}

.llm-upgrade .csfn {
  font-size: 12px;
  color: var(--muted);
}

.llm-upgrade .cstm {
  margin-left: auto;
  font-size: 11px;
  color: var(--dim);
}

.llm-upgrade .csc:focus {
  outline: 2px solid rgba(196,63,122,.55);
  outline-offset: 3px;
}

@media(max-width:860px) {
  .llm-upgrade .csg {
    grid-template-columns: 1fr;
  }
}

/* Finished Modal CSS */
.llm-upgrade .modal {
  position: fixed;
  inset: 0;
  background: rgba(3,2,9,.92);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  opacity: 0;
  visibility: hidden;
  transition: opacity .3s ease, visibility .3s ease;
}

.llm-upgrade .modal.on {
  opacity: 1;
  visibility: visible;
}

.llm-upgrade .mbox {
  background: var(--bg3);
  border: 1px solid var(--ln2);
  border-radius: 18px;
  max-width: 640px;
  width: 100%;
  max-height: 88vh;
  overflow-y: auto;
  position: relative;
  box-shadow: 0 48px 120px rgba(0,0,0,.8);
  transform: translateY(20px) scale(.97);
  transition: transform .4s cubic-bezier(.22,1,.36,1);
}

.llm-upgrade .modal.on .mbox {
  transform: translateY(0) scale(1);
}

.llm-upgrade .mbox::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  animation: llmGradientShift 5s ease infinite;
  border-radius: 18px 18px 0 0;
}

.llm-upgrade .mh {
  padding: 24px 56px 20px 26px;
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  background: rgba(20,17,34,.97);
  z-index: 3;
}

.llm-upgrade .mx {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(255,255,255,.06);
  border: 1px solid var(--ln2);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 15px;
  color: var(--muted);
  transition: .25s;
}

.llm-upgrade .mx:hover {
  color: #fff;
  background: rgba(255,255,255,.12);
}

.llm-upgrade .mind {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .16em;
  text-transform: uppercase;
  margin-bottom: 4px;
  display: block;
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .mtitle {
  font-size: 20px;
  font-weight: 600;
  color: var(--silver);
  display: block;
}

.llm-upgrade .msub {
  font-size: 12px;
  color: var(--muted);
  display: block;
}

.llm-upgrade .mb {
  padding: 24px 26px 32px;
}

.llm-upgrade .mimg {
  height: 176px;
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid var(--line);
  margin-bottom: 22px;
}

.llm-upgrade .mimg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
}

.llm-upgrade .ms {
  margin-bottom: 20px;
}

.llm-upgrade .mst {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
  display: block;
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .mmet {
  display: grid;
  grid-template-columns: repeat(2,1fr);
  gap: 9px;
}

.llm-upgrade .mm {
  text-align: center;
  padding: 13px;
  background: rgba(232,97,42,.06);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.llm-upgrade .mm strong {
  display: block;
  font-size: 26px;
  font-weight: 700;
  line-height: 1;
  margin-bottom: 3px;
  background: linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: llmGradientShift 5s ease infinite;
}

.llm-upgrade .mm span {
  font-size: 9.5px;
  color: var(--muted);
  text-transform: uppercase;
}

.llm-upgrade .mlist {
  list-style: none;
  margin: 0;
  padding: 0;
}

.llm-upgrade .mlist li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 9px 0;
  border-bottom: 1px solid rgba(255,255,255,.04);
  font-size: 14px;
  color: var(--body);
}

.llm-upgrade .mlist li:last-child {
  border-bottom: none;
}

.llm-upgrade .mlc {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  flex-shrink: 0;
  margin-top: 2px;
  background: rgba(34,197,94,.1);
  border: 1px solid rgba(34,197,94,.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  color: #22C55E;
}

.llm-upgrade .mdesc {
  font-size: 14px;
  color: var(--muted);
  line-height: 1.78;
  padding: 14px 16px;
  background: rgba(255,255,255,.03);
  border-radius: 8px;
  border-left: 2px solid rgba(196,63,122,.5);
}

@media(max-width:860px) {
  .llm-upgrade .csg {
    grid-template-columns: 1fr;
  }
}

html.dgs-modal-open, body.dgs-modal-open { overflow: hidden; }

